WITH department_summary AS (SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary, MIN(hire_date) AS first_hire_date FROM employees GROUP BY dept_id) SELECT departments.id, departments.location, departments.budget, department_summary.stddev_salary, department_summary.first_hire_date FROM departments JOIN department_summary ON departments.id = department_summary.dept_id WHERE department_summary.stddev_salary >= 31;
